/**
 * Raw API types — the shapes the Kineo backend answers with.
 *
 * Two layers, split by the question "can code check this?":
 *
 * 1. `api.gen.ts` — generated by `openapi-typescript` from the backend document
 *    (`/api-json` on the running dist; regenerate with `bun run api:types`,
 *    never edited by hand; the types are committed, the document is not). It is
 *    the only file in this directory that is allowed to be wrong purely by
 *    being stale, and the conscious regenerate-review-commit step after each
 *    backend merge is what keeps staleness visible rather than silent — while
 *    `api-routes.spec.ts` proves the route names it publishes stay audited.
 * 2. This file — the façade the codebase imports: named aliases to the
 *    generated components, the runtime vocabulary (`..._STATUSES` arrays, which
 *    a generated type cannot provide), the generic pagination helpers, and
 *    layout-independent shapes. `ApiUser` stays hand-written because it is a
 *    better-auth session type that the OpenAPI document does not publish.
 *
 * Type-level parity tests in `api.contract.spec.ts` pin the runtime vocabulary
 * and the façade aliases to the generated unions, so a backend change that
 * drops or renames a value fails here first.
 */

import type { components } from "./api.gen";

/**
 * The schemas the backend publishes. Request DTOs are in there too; only
 * response shapes are aliased here — payload types where forms are built are
 * named beside the services that send them.
 */
type Wire = components["schemas"];

/** Better-Auth user (mirrors the backend Prisma User model). */
export interface ApiUser {
  id: string;
  name: string | null;
  email: string;
  emailVerified: boolean;
  image?: string | null;
  createdAt: string;
  updatedAt: string;
}

/**
 * Lifecycle, in the order a posting moves through it.
 *
 * A const array rather than a bare union so the same list exists at runtime:
 * the zeroed counters that stand in for a response without its breakdown have
 * to enumerate the same statuses, and a hand-copied second list is a silent
 * drift.
 */
export const REPLACEMENT_LISTING_STATUSES = [
  "DRAFT",
  "OPEN",
  "IN_DISCUSSION",
  "FULL",
  "FILLED",
  "CLOSED",
  "CLOSED_NO_CANDIDATE",
  "CANCELLED",
] as const;

export type ReplacementListingStatus =
  (typeof REPLACEMENT_LISTING_STATUSES)[number];

export type ApiReplacementListing = Wire["ReplacementListing"];

/**
 * Per-specialty totals for the whole collection, as `GET
 * /replacement-listings/facets` returns them.
 *
 * Every specialty is present, including the ones holding nothing: the summary
 * panels draw one row per specialty in a fixed order, so a missing key would
 * drop a row rather than empty it. The published document can only say
 * `{ [key: string]: number }` (a record keyed by an enum has no OpenAPI 3.0
 * one-line form), so the stricter client type is kept and pinned by a parity
 * test against what the document publishes.
 */
export type ApiListingSpecialtyCounts = Record<Specialty, number>;

export type ApiListingFacets = Wire["ListingFacets"];

export type ApiListingPlaces = Wire["ListingPlaces"];

/** One posting at a place, as the map's popup previews it. */
export type ApiPlaceListing =
  ApiListingPlaces["places"][number]["listings"][number];

/** A place the map is drawn from, with the postings that sit on it. */
export type ApiListingPlace = ApiListingPlaces["places"][number];

/**
 * The page of the reader's ordering that holds one posting, `null` when the
 * current filters do not show it.
 */
export type ApiListingPageOf = Wire["ListingPageOf"];

/**
 * One application, as `GET /applications/mine` answers it — with the decision
 * that ended it (`decisionSource`, null while it is open) and, on the reads the
 * piggyback practice on, the embedded listing and applicant. On the applicant,
 * `anonymized` is what says the candidate erased their account (art. 17 GDPR):
 * their fields are blank by construction, and a blank name is also what an
 * applicant who never filled theirs in looks like — the flag is the only
 * trustworthy signal.
 */
export type ApiApplication = Wire["Application"];

export const APPLICATION_STATUSES = [
  "PENDING",
  "SHORTLISTED",
  "ACCEPTED",
  "REJECTED",
  "WITHDRAWN",
] as const;

export type ApplicationStatus = (typeof APPLICATION_STATUSES)[number];

/**
 * Which outcome ended the application, when one has.
 *
 * The status alone cannot answer the question the applicant actually has: two
 * things land on `REJECTED` — the practice refused this person, or an account
 * was erased — and they read nothing alike. `WITHDRAWN` mixes a self-service
 * withdrawal with one written by the account erasure too.
 *
 * These four are a mirror of the backend's `DecisionSource` enum, and the
 * only four it can ever send — the code reads by this value, so a name the
 * database cannot produce is dead weight and a gap it *does* produce is a
 * crash at read time. Complete, and nothing else. Const array, not a bare
 * union — see `REPLACEMENT_LISTING_STATUSES`.
 *
 * Which account was erased is not in this value: `SYSTEM` covers both, and the
 * status tells them apart — `WITHDRAWN` when the candidate erased their own,
 * `REJECTED` when the practice's account went. Null while the application is
 * still open: nobody has decided yet.
 */
export const APPLICATION_DECISION_SOURCES = [
  "CANDIDATE_WITHDREW",
  "PRACTICE_ACCEPTED",
  "PRACTICE_REJECTED",
  "SYSTEM",
] as const;

export type ApplicationDecisionSource =
  (typeof APPLICATION_DECISION_SOURCES)[number];

/**
 * The three situations a rejected application can be.
 *
 * Named by the backend and computed there: `REJECTED` alone covers a practice
 * refusing this person, another candidate being retained, and the posting
 * leaving circulation, and those need three different reactions. The backend
 * derives it from fields it already stores, so the client never re-decides
 * which is which.
 */
export const APPLICATION_REJECTION_BUCKETS = [
  "PASSED_OVER",
  "POSTING_ENDED",
  "REFUSED",
] as const;

export type ApplicationRejectionBucket =
  (typeof APPLICATION_REJECTION_BUCKETS)[number];

/**
 * Per-situation totals, over the whole collection.
 *
 * Optional because an older backend does not send it; every reader fills the
 * gap with 0, which shows an empty chip rather than a broken page.
 */
export type ApiApplicationBucketCounts = NonNullable<
  Wire["PaginatedApplications"]["meta"]["bucketCounts"]
>;

/**
 * A paginated response.
 *
 * `counts` is deliberately left to each caller rather than typed here: the
 * applications endpoints break their totals down by `ApplicationStatus`, the
 * listings one by `ReplacementListingStatus`. A single shared field would have
 * to be the union of both, so picking the wrong one would type-check and then
 * read `undefined` off a status that never existed. Each service names its own
 * shape instead (see `ListingStatusCounts` / `ReceivedApplicationCounts`).
 */
export interface ApiPaginated<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

/** The applications page: the slice plus the totals behind its status chips. */
export interface ApiApplicationPage<T> extends ApiPaginated<T> {
  meta: ApiPaginated<T>["meta"] & {
    /** Only the applications endpoints return a breakdown. */
    counts: ApiApplicationStatusCounts;
    /** Per-situation totals for the rejected applications. Absent on older backends. */
    bucketCounts?: ApiApplicationBucketCounts;
    /**
     * Open applications the practice has not opened yet, over the whole
     * collection. A backend one release behind sends none, and a caller reads
     * that as zero rather than paging the collection to count it.
     */
    unseenOpenCount?: number;
    /**
     * Applications that got an answer, withdrawn ones excluded — the numerator
     * of the dashboard's response rate, sent beside the totals that form its
     * denominator so the two cannot describe different collections.
     */
    respondedCount?: number;
  };
}

/**
 * One counter per value of `S`, plus the `total` across all of them.
 *
 * Generic over the key set because the API serves three different breakdowns —
 * by application status, by listing status, by decision source — and they all
 * have this shape. The wire type and the presentation contract that describe a
 * given breakdown stay separately named, being different layers, but both are
 * written this way so they cannot drift apart in shape.
 *
 * See `lib/counts.ts` for the zeroed stand-in used when a response carries no
 * breakdown.
 */
export type StatusCounts<S extends string> = Record<S | "total", number>;

/** Server-computed totals for a collection of applications, by status. */
export type ApiApplicationStatusCounts = StatusCounts<ApplicationStatus>;

/**
 * One medical specialty a profile can carry, and the profile type a member
 * declares.
 *
 * Ports of the backend's Prisma enums, kept as plain unions: they also name a
 * fork of the vocabulary the presentation layer loves — `SPECIALTY_LABELS`,
 * `PROFILE_TYPE_LABELS` — whose keys must enumerate exactly these, and a
 * parity test pins both sides to the generated unions the document publishes.
 */
export type Specialty =
  | "GENERALIST"
  | "DENTIST"
  | "DERMATOLOGIST"
  | "PSYCHIATRIST"
  | "OTHER";

export type ProfileType = "INSTALLED" | "REPLACEMENT" | "BOTH";

export type ApiProfile = Wire["Profile"];
